import networkx as nx
import itertools

def indep_num(G):
    # exact max indep set
    nodes = list(G.nodes())
    for k in range(len(nodes), 0, -1):
        for s in itertools.combinations(nodes, k):
            sub = G.subgraph(s)
            if sub.number_of_edges() == 0:
                return k
    return 0

def edge_cover_num(G):
    # min edge cover
    edges = list(G.edges())
    nodes = set(G.nodes())
    for k in range(1, len(nodes) + 1):
        for es in itertools.combinations(edges, k):
            covered = set()
            for u, v in es:
                covered.add(u)
                covered.add(v)
            if covered == nodes:
                return k
    return len(nodes)

for idx, G in enumerate(nx.graph_atlas_g()):
